import itertools
feats={'1':np.ones_like(P),'P':P,'P2':P**2,'1/P':1/P,'t':t,'tP':t*P,'t2':t**2,'sinT':np.sin(t),'cosT':np.cos(t),'expt':np.exp(-t),'logP':np.log(P),'t/P':t/P,'P*logP':P*np.log(P),'1/t':1/t,'sqrtP':np.sqrt(P),'P/t':P/t}
names=list(feats)
best=[]
for k in [2,3,4]:
    for comb in itertools.combinations(names,k):
        A=np.column_stack([feats[n] for n in comb])
        c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
        r=np.sum((A@c-dP_dt)**2)/np.sum((dP_dt-dP_dt.mean())**2)
        best.append((r,comb,np.round(c,4)))
best.sort(key=lambda x:x[0])
for b in best[:10]: print(b)

